// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  GatewayHealth.swift
//  Latchkey
//
//  F22: the lights of the app bar's gateway row. Each remembered gateway is
//  probed directly, on its own port, with discovery's fingerprint and
//  discovery's session (proxy only, no cookies, no redirects): no sweep of
//  the tailnet. It runs only while the row is on screen, so a retracted bar
//  costs nothing, and a verdict younger than `freshFor` is not asked again.
//
//  A light is a forecast, never a gate: a red gateway can still be chosen,
//  and F4 reports the real load (F5 §7's rule).
//

import Foundation

@MainActor
final class GatewayHealth: ObservableObject {
    typealias Verdict = GatewayChipState.Verdict

    @Published private(set) var verdicts: [String: Verdict] = [:]

    /// How long a verdict stands before the row asks again.
    static let freshFor: Duration = .seconds(30)

    private let model: TSNetModel
    private var checkedAt: [String: ContinuousClock.Instant] = [:]
    private var inFlight: [String: Task<Void, Never>] = [:]

    init(model: TSNetModel) {
        self.model = model
    }

    /// Probes each of `origins` whose verdict is missing or stale, all at
    /// once. A stale verdict keeps showing until its replacement lands: the
    /// row must not flash amber every 30 s. An origin the tailnet does not
    /// carry is never probed (it would leave the tailnet).
    func refresh(_ origins: [String]) {
        guard let proxy = model.proxyConfiguration, let policy = model.proxyPolicy else { return }
        let now = ContinuousClock.now
        for origin in origins where inFlight[origin] == nil {
            if let at = checkedAt[origin], now - at < Self.freshFor { continue }
            guard let endpoint = GatewayEndpoint(origin: origin),
                  policy.matchingRule(for: endpoint.host) != nil else { continue }
            if verdicts[origin] == nil { verdicts[origin] = .checking }
            inFlight[origin] = Task { [weak self] in
                let session = GatewayDiscovery.makeSession(proxy: proxy)
                defer { session.invalidateAndCancel() }
                let verdict = await GatewayDiscovery.probe(endpoint.host, port: endpoint.port, session: session)
                guard !Task.isCancelled, let self else { return }
                self.inFlight[origin] = nil
                self.checkedAt[origin] = .now
                self.verdicts[origin] = switch verdict {
                case .gateway: .answering
                case .notGateway: .notGateway
                case .failed: .notAnswering
                }
                logger.log("Gateway row: \(endpoint.displayName) \(String(describing: self.verdicts[origin]!))")
            }
        }
    }

    /// The row has gone: nothing is probed for a bar no one can see. A
    /// cancelled probe leaves no verdict time, so the next show asks again.
    func stop() {
        for task in inFlight.values { task.cancel() }
        inFlight = [:]
    }
}

// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  GatewayRow.swift
//  Latchkey
//
//  F22: the app bar's row of gateways. One chip per remembered gateway, the
//  one in use first, each with the dashboard's instance-bar light; one tap
//  on another switches to it directly. The dashboard's own instance bar
//  cannot do this from a phone: its remotes are plain-HTTP frames on the
//  gateway's loopback (F5 §5). These are gateways the app itself opens.
//
//  It lives in the bar, so it is there only when the bar is (F15): nothing
//  of it is on the page, and it adds no height.
//

import SwiftUI

struct GatewayRow: View {
    /// In order, in use first (`GatewayChipState.order`); never empty.
    let origins: [String]
    let current: String
    let load: GatewayChipState.Load
    /// Whether the tailnet has a rule set yet, and whether it carries a host.
    let ready: Bool
    let carried: (String) -> Bool
    @ObservedObject var health: GatewayHealth
    let onSwitch: (String) -> Void

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 4) {
                ForEach(origins, id: \.self) { origin in
                    GatewayChip(origin: origin, inUse: origin == current, state: state(origin)) {
                        onSwitch(origin)
                    }
                }
            }
            .padding(.horizontal, 2)
        }
        .scrollBounceBehavior(.basedOnSize, axes: .horizontal)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("gateway-row")
        // Probes only while the row is on screen, and again every
        // `freshFor` while it stays (F22 §4).
        .task(id: others) {
            while !Task.isCancelled {
                health.refresh(others)
                try? await Task.sleep(for: GatewayHealth.freshFor)
            }
        }
        .onDisappear { health.stop() }
    }

    private var others: [String] { origins.filter { $0 != current } }

    private func state(_ origin: String) -> GatewayChipState {
        if origin == current { return .current(load) }
        let host = URL(string: origin)?.host() ?? ""
        return .other(ready: ready, carried: !host.isEmpty && carried(host), verdict: health.verdicts[origin])
    }
}

/// One chip: the dashboard's `e8`, in SwiftUI. A bordered 26 pt capsule-ish
/// button, 12 pt text and a 6 pt light; the one in use filled and bold.
private struct GatewayChip: View {
    let origin: String
    let inUse: Bool
    let state: GatewayChipState
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 5) {
                Circle()
                    .fill(Self.color(state.light))
                    .frame(width: 6, height: 6)
                Text(GatewayChipState.shortName(origin))
                    .font(.system(size: 12, weight: inUse ? .bold : .regular))
                    .lineLimit(1)
                    .truncationMode(.tail)
                    .frame(maxWidth: 140, alignment: .leading)
                    .fixedSize(horizontal: true, vertical: false)
                if !state.word.isEmpty && state.light != .ok {
                    Text(state.word)
                        .font(.system(size: 11))
                        .foregroundStyle(state.light == .muted ? Color.secondary : Self.color(state.light))
                        .lineLimit(1)
                        .fixedSize()
                }
            }
            .foregroundStyle(inUse ? Color.accentColor : Color.primary)
            .padding(.horizontal, 8)
            .frame(height: 26)
            .background {
                RoundedRectangle(cornerRadius: 6)
                    .fill(inUse ? Color.accentColor.opacity(0.15) : Color.clear)
            }
            .overlay {
                if !inUse {
                    RoundedRectangle(cornerRadius: 6)
                        .strokeBorder(Color.secondary.opacity(0.35), lineWidth: 1)
                }
            }
            .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 6))
            .frame(minHeight: 44)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        // The chip in use is not a switch, and a gateway off the tailnet may
        // not be chosen at all; the dimmed look is the not-enabled trait.
        .disabled(!state.tappable)
        .opacity(!state.tappable && !inUse ? 0.6 : 1)
        .accessibilityLabel(GatewayChipState.shown(origin) + (inUse ? ", in use" : ""))
        .accessibilityValue(state.word)
        .accessibilityIdentifier("gateway-chip-\(GatewayChipState.shown(origin))")
    }

    /// KiroCrew's `--ok`, `--warn`, `--danger` and `--muted`, as the system's
    /// own green, orange, red and grey, which adapt to light and dark.
    static func color(_ light: GatewayChipState.Light) -> Color {
        switch light {
        case .ok: return .green
        case .warn: return .orange
        case .danger: return .red
        case .muted: return .gray
        }
    }
}

